-- Paste this whole line into Roblox Studio's Command Bar (View -> Command Bar) and press Enter.
-- It finds the creature models you just imported (anywhere in Workspace) and moves them into
-- ReplicatedStorage.CreatureMeshes with the right names. Run it again any time you import more.
local ids={"GlowSprite","MossToad","PixieMoth","MoonRabbit","FaeDragonling","CinderImp","LavaSalamander","EmberFox","FlameDrake","Phoenix","FrostPup","IceWisp","CrystalStag","FrostWyrm","GlacialGriffin","AuroraKirin","StormOwl","CloudSerpent","ThunderGriffin","CelestialPegasus","StarDragon","VoidLeviathan","ArenaBasilisk","GladiatorManticore","TitanUnicorn"} local RS=game:GetService("ReplicatedStorage") local folder=RS:FindFirstChild("CreatureMeshes") or Instance.new("Folder",RS) folder.Name="CreatureMeshes" local moved=0 for _,obj in ipairs(workspace:GetChildren()) do if obj:IsA("Model") or obj:IsA("MeshPart") then local clean=string.lower((obj.Name:gsub("[^%w]",""))) for _,id in ipairs(ids) do if string.sub(clean,1,#id)==string.lower(id) then local old=folder:FindFirstChild(id) if old then old:Destroy() end obj.Name=id obj.Parent=folder moved+=1 break end end end end print(("Moved %d creature model(s) into ReplicatedStorage.CreatureMeshes. Missing: %s"):format(moved,(function() local m={} for _,id in ipairs(ids) do if not folder:FindFirstChild(id) then table.insert(m,id) end end return #m==0 and "none!" or table.concat(m,", ") end)()))
